var n=`0876-beef-kala-bhuna`;var i=`world-0876`;var t=`BD`;var s=`south-asia`;var r=4;var o=192;var u={en:`Beef Kala Bhuna`,ua:`Кала бгуна з яловичини`};var d={en:`Beef Kala Bhuna is a Bangladesh dish made with beef chuck, yellow onion, ginger-garlic paste, serrano pepper. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Кала бгуна з яловичини, страва кухні країни Бангладеш. Основні складники: яловича лопатка, жовта цибуля, імбирно-часникова паста, перець серрано. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 15 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 15 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:15,i:[[`beef-chuck`,900,`g`],[`mustard-oil`,65,`ml`],[`yellow-onion`,245,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 14 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 14 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:14,i:[[`ginger-garlic-paste`,30,`g`],[`ground-cumin`,8,`g`],[`ground-coriander`,8,`g`],[`kashmiri-chili-powder`,6,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 145 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 145 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:145,i:[[`water`,690,`ml`],[`garam-masala`,7,`g`],[`table-salt`,null,`to_taste`]]},{en:`Simmer the liquid and flavorings uncovered for about 15 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 15 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:15,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`serrano-pepper`,2,`pcs`]]}];var l={slug:n,id:i,country:`BD`,region:s,servings:4,minutes:192,title:u,text:d,steps:g};export{t as country,l as default,i as id,o as minutes,s as region,r as servings,n as slug,g as steps,d as text,u as title};